def solve():
    # dp[j][S_j][S_1]
    # S_j = 0, 1, 2
    # j = 1 to 21
    # S_j = 0: neither R_{1,j}, R_{2,j}
    # S_j = 1: R_{1,j}
    # S_j = 2: R_{2,j}
    # R_{1,j} = j, R_{2,j} = j+21

    dp = [[[0] * 3 for _ in range(3)] for _ in range(22)]

    # Initial state for j=1
    dp[1][0][0] = 1
    dp[1][1][1] = 1
    dp[1][2][2] = 1

    for j in range(2, 22):
        for s1 in range(3):
            # dp[j][0][s1] - neither R_{1,j} nor R_{2,j}
            dp[j][0][s1] = dp[j-1][0][s1] + dp[j-1][1][s1] + dp[j-1][2][s1]
            # dp[j][1][s1] - R_{1,j}
            # R_{1,j} is adjacent to R_{1,j-1} (S_{j-1}=1)
            dp[j][1][s1] = dp[j-1][0][s1] + dp[j-1][2][s1]
            # dp[j][2][s1] - R_{2,j}
            # R_{2,j} is adjacent to R_{2,j-1} (S_{j-1}=2)
            dp[j][2][s1] = dp[j-1][0][s1] + dp[j-1][1][s1]

    total = 0
    for s21 in range(3):
        for s1 in range(3):
            total += dp[21][s21][s1]

    # Subtract the forbidden case: S_21=1 (R_{1,21}) and S_1=2 (R_{2,1})
    # Since |R_{1,21} - R_{2,1}| = |21 - 22| = 1
    total -= dp[21][1][2]
    return total

print(solve())
